from __future__ import annotations

"""Webhook event models for Stripe-style billing notifications.

The billing system reacts to a small slice of Stripe events. Each event is a
thin envelope around an invoice plus a delivery sequence number that Stripe
assigns roughly in creation order. Webhook delivery is at-least-once, so the
same event id can show up twice and two events for one invoice can arrive in
either order.
"""

from dataclasses import dataclass, field


SUPPORTED_EVENT_TYPES = frozenset(
    {
        "invoice.payment_failed",
        "invoice.payment_succeeded",
        "invoice.created",
        "invoice.finalized",
    }
)


def _require(label: str, value: str | None) -> str:
    if value is None or not str(value).strip():
        raise ValueError(f"{label} is required")
    return str(value).strip()


@dataclass(frozen=True)
class InvoiceRef:
    """Identifies the invoice an event is about.

    `attempt` is the dunning retry attempt number Stripe increments each time it
    re-tries a failed charge. `created_unix` is when the invoice itself was
    created, used to tell the latest open invoice from older ones.
    """

    invoice_id: str
    subscription_id: str
    attempt: int
    created_unix: int

    def __post_init__(self) -> None:
        inv = _require("invoice_id", self.invoice_id)
        sub = _require("subscription_id", self.subscription_id)
        if self.attempt < 0:
            raise ValueError("attempt must be non-negative")
        if self.created_unix < 0:
            raise ValueError("created_unix must be non-negative")
        object.__setattr__(self, "invoice_id", inv)
        object.__setattr__(self, "subscription_id", sub)


@dataclass(frozen=True)
class DunningEvent:
    """A single webhook delivery.

    `event_id` is unique per logical event but can be redelivered. `sequence` is
    Stripe's monotonic-ish ordering hint; smaller means earlier in Stripe's
    timeline even if it lands later on our endpoint.
    """

    event_id: str
    event_type: str
    invoice: InvoiceRef
    sequence: int
    received_unix: int
    metadata: dict[str, object] = field(default_factory=dict)

    def __post_init__(self) -> None:
        eid = _require("event_id", self.event_id)
        etype = _require("event_type", self.event_type)
        if etype not in SUPPORTED_EVENT_TYPES:
            raise ValueError(f"unsupported event_type: {etype}")
        if self.sequence < 0:
            raise ValueError("sequence must be non-negative")
        object.__setattr__(self, "event_id", eid)
        object.__setattr__(self, "event_type", etype)

    @property
    def invoice_id(self) -> str:
        return self.invoice.invoice_id

    @property
    def subscription_id(self) -> str:
        return self.invoice.subscription_id

    def is_failure(self) -> bool:
        return self.event_type == "invoice.payment_failed"

    def is_success(self) -> bool:
        return self.event_type == "invoice.payment_succeeded"


def make_invoice(
    *,
    invoice_id: str,
    subscription_id: str,
    attempt: int = 0,
    created_unix: int = 0,
) -> InvoiceRef:
    return InvoiceRef(
        invoice_id=invoice_id,
        subscription_id=subscription_id,
        attempt=attempt,
        created_unix=created_unix,
    )


def make_event(
    *,
    event_id: str,
    event_type: str,
    invoice: InvoiceRef,
    sequence: int,
    received_unix: int = 0,
    metadata: dict[str, object] | None = None,
) -> DunningEvent:
    return DunningEvent(
        event_id=event_id,
        event_type=event_type,
        invoice=invoice,
        sequence=sequence,
        received_unix=received_unix,
        metadata=dict(metadata or {}),
    )


def event_label(event: DunningEvent) -> str:
    return (
        f"{event.event_type} inv={event.invoice_id} "
        f"attempt={event.invoice.attempt} seq={event.sequence}"
    )


def sort_by_stripe_order(events: list[DunningEvent]) -> list[DunningEvent]:
    """Return events in the order Stripe created them, not delivery order."""
    return sorted(events, key=lambda e: (e.sequence, e.received_unix))

