from __future__ import annotations

"""Transition policy: given the current record and an event, decide the next
state and whether the event should be applied at all.

This is pure decision logic. It reads the subscription record and the event but
never mutates the store; the processor owns mutation. Keeping it separate makes
the rules easy to reason about and lets us replay an event list deterministically.
"""

from dunning_events import DunningEvent
from subscription_states import (
    ACTIVE,
    CANCELED,
    PAST_DUE,
    SubscriptionRecord,
)


class PolicyDecision:
    """Result of evaluating one event against a record.

    `apply` is whether the processor should act on it. `next_state` is the state
    to move to when `apply` is true. `reason` is a short tag for logging and
    tests.
    """

    __slots__ = ("apply", "next_state", "reason")

    def __init__(self, apply: bool, next_state: str | None, reason: str) -> None:
        self.apply = apply
        self.next_state = next_state
        self.reason = reason

    def __repr__(self) -> str:  # pragma: no cover - debugging aid
        return f"PolicyDecision(apply={self.apply}, next_state={self.next_state!r}, reason={self.reason!r})"


def _event_is_for_known_latest(record: SubscriptionRecord, event: DunningEvent) -> bool:
    """Does this event concern the newest invoice we have tracked?"""
    return record.is_latest_invoice(event.invoice_id, event.invoice.created_unix)


def decide_failure(record: SubscriptionRecord, event: DunningEvent) -> PolicyDecision:
    """A payment_failed moves an active subscription into dunning.

    A failure for an invoice we already resolved is stale (the charge later
    succeeded) and must not reopen dunning.
    """
    if record.is_resolved(event.invoice_id):
        return PolicyDecision(False, None, "failure_for_resolved_invoice")

    if record.state == CANCELED:
        return PolicyDecision(False, None, "subscription_canceled")

    # An older invoice failing after a newer one already moved us forward is
    # noise from out-of-order delivery.
    if not _event_is_for_known_latest(record, event):
        return PolicyDecision(False, None, "failure_for_stale_invoice")

    return PolicyDecision(True, PAST_DUE, "charge_failed")


def decide_success(record: SubscriptionRecord, event: DunningEvent) -> PolicyDecision:
    """A payment_succeeded should clear dunning for the relevant invoice.

    Stripe fires this both for first-attempt charges and for smart retries after
    one or more failures. Either way a successful charge on the current invoice
    means the customer is paid up.
    """
    if record.state == CANCELED:
        return PolicyDecision(False, None, "subscription_canceled")

    if not _event_is_for_known_latest(record, event):
        return PolicyDecision(False, None, "success_for_stale_invoice")

    if record.state == ACTIVE:
        return PolicyDecision(True, ACTIVE, "first_charge_succeeded")

    return PolicyDecision(False, None, "no_dunning_to_clear")


def decide(record: SubscriptionRecord, event: DunningEvent) -> PolicyDecision:
    """Top-level dispatch used by the processor."""
    if event.is_failure():
        return decide_failure(record, event)
    if event.is_success():
        return decide_success(record, event)
    # invoice.created / invoice.finalized do not change dunning state; they only
    # advance which invoice is the latest, handled by the processor.
    return PolicyDecision(False, None, "non_dunning_event")


def is_terminal_success(decision: PolicyDecision) -> bool:
    return decision.apply and decision.next_state == ACTIVE


def is_entering_dunning(decision: PolicyDecision) -> bool:
    return decision.apply and decision.next_state == PAST_DUE


def explain_decision(record: SubscriptionRecord, event: DunningEvent) -> dict[str, object]:
    decision = decide(record, event)
    return {
        "subscription_id": event.subscription_id,
        "invoice_id": event.invoice_id,
        "event_type": event.event_type,
        "current_state": record.state,
        "apply": decision.apply,
        "next_state": decision.next_state,
        "reason": decision.reason,
    }

