from __future__ import annotations

"""Higher-level workflow used by billing ops dashboards.

Wraps the processor to ingest streams of webhook events and produce summaries:
how many subscriptions are healthy, how many are stuck in dunning, and which
ones never cleared after a successful payment. Billing ops watches the
"stuck after success" list to catch customers who paid but still look past_due.
"""

from dunning_events import DunningEvent
from subscription_states import ACTIVE, PAST_DUE, SubscriptionStore, describe_record
from webhook_processor import ProcessResult, WebhookProcessor


class DunningWorkflow:
    def __init__(self) -> None:
        self.processor = WebhookProcessor(SubscriptionStore())
        self._results: list[ProcessResult] = []

    def ingest(self, event: DunningEvent) -> ProcessResult:
        result = self.processor.process(event)
        self._results.append(result)
        return result

    def ingest_all(self, events: list[DunningEvent]) -> list[ProcessResult]:
        return [self.ingest(event) for event in events]

    def state_of(self, subscription_id: str) -> str | None:
        return self.processor.state_of(subscription_id)

    def results(self) -> list[ProcessResult]:
        return list(self._results)

    def summary(self) -> dict[str, object]:
        store = self.processor.store
        snapshot = store.snapshot()
        active = [s for s, st in snapshot.items() if st == ACTIVE]
        past_due = [s for s, st in snapshot.items() if st == PAST_DUE]
        return {
            "subscription_count": len(snapshot),
            "active_count": len(active),
            "past_due_count": len(past_due),
            "active_subscriptions": sorted(active),
            "past_due_subscriptions": sorted(past_due),
            "events_ingested": len(self._results),
        }

    def stuck_after_success(self) -> list[str]:
        """Subscriptions that saw a successful payment but are still past_due.

        With correct transitions this list is always empty. Ops uses it as an
        alarm when a paid customer is still flagged for collections.
        """
        succeeded_subs: set[str] = set()
        for result in self._results:
            if result.reason in {
                "first_charge_succeeded",
                "retry_succeeded",
                "no_dunning_to_clear",
                "success_for_stale_invoice",
            }:
                succeeded_subs.add(result.subscription_id)
        stuck = []
        for sub in succeeded_subs:
            if self.processor.state_of(sub) == PAST_DUE:
                stuck.append(sub)
        return sorted(stuck)

    def record_view(self, subscription_id: str) -> dict[str, object] | None:
        record = self.processor.store.get(subscription_id)
        return None if record is None else describe_record(record)


def summarize_results(results: list[ProcessResult]) -> dict[str, object]:
    applied = [r for r in results if r.applied]
    duplicates = [r for r in results if r.duplicate]
    by_reason: dict[str, int] = {}
    for result in results:
        by_reason[result.reason] = by_reason.get(result.reason, 0) + 1
    return {
        "total": len(results),
        "applied": len(applied),
        "duplicates": len(duplicates),
        "by_reason": by_reason,
    }


def transitions_to_active(results: list[ProcessResult]) -> int:
    return sum(1 for r in results if r.applied and r.to_state == ACTIVE)


def transitions_to_past_due(results: list[ProcessResult]) -> int:
    return sum(1 for r in results if r.applied and r.to_state == PAST_DUE)


def workflow_health(workflow: DunningWorkflow) -> str:
    summary = workflow.summary()
    if summary["subscription_count"] == 0:
        return "idle"
    if workflow.stuck_after_success():
        return "stuck_dunning_detected"
    if summary["past_due_count"]:
        return "collections_active"
    return "all_current"

