from __future__ import annotations

"""Subscription dunning state plus the in-memory store the processor mutates.

States mirror the lifecycle Stripe exposes on a subscription. We only model the
slice that matters for dunning:

    active     -> paid and healthy, no open dunning
    past_due   -> a charge failed and Stripe is retrying
    canceled   -> dunning gave up (out of scope for transitions here)

The store keeps, per subscription, the current state and a little bookkeeping
about which invoice we last acted on so the processor can decide whether an
incoming event is relevant or stale.
"""

from dataclasses import dataclass, field


ACTIVE = "active"
PAST_DUE = "past_due"
CANCELED = "canceled"

KNOWN_STATES = frozenset({ACTIVE, PAST_DUE, CANCELED})

# States that still owe money / are in a dunning cycle.
DUNNING_STATES = frozenset({PAST_DUE})


@dataclass
class SubscriptionRecord:
    """Mutable per-subscription bookkeeping.

    `latest_invoice_id` is the most recent invoice we have seen for this sub.
    `latest_invoice_created` is that invoice's creation timestamp, used to
    ignore events about older invoices. `resolved_invoices` records invoice ids
    that already reached a terminal success so a replayed failure cannot reopen
    them.
    """

    subscription_id: str
    state: str = ACTIVE
    latest_invoice_id: str | None = None
    latest_invoice_created: int = -1
    last_failed_attempt: int = 0
    resolved_invoices: set[str] = field(default_factory=set)

    def __post_init__(self) -> None:
        if self.state not in KNOWN_STATES:
            raise ValueError(f"unknown state: {self.state}")

    def is_in_dunning(self) -> bool:
        return self.state in DUNNING_STATES

