from __future__ import annotations

"""Applies webhook events to the subscription store.

The processor is the only place that mutates state. For each event it:

1. Skips events it has already handled (at-least-once delivery means duplicates).
2. Updates which invoice is the latest one seen for the subscription.
3. Asks the policy what to do, then applies the decision.
4. Records terminal successes so a late, replayed failure cannot reopen dunning.

Events can arrive out of Stripe's creation order, so the processor must not
assume the event it just received is newer than what it already applied.
"""

from dataclasses import dataclass

from dunning_events import DunningEvent, sort_by_stripe_order
from dunning_policy import decide, is_terminal_success
from subscription_states import (
    ACTIVE,
    SubscriptionRecord,
    SubscriptionStore,
    describe_record,
)


@dataclass
class ProcessResult:
    event_id: str
    subscription_id: str
    invoice_id: str
    applied: bool
    duplicate: bool
    from_state: str
    to_state: str
    reason: str


class WebhookProcessor:
    def __init__(self, store: SubscriptionStore | None = None) -> None:
        self.store = store or SubscriptionStore()
        self._handled_event_ids: set[str] = set()

    def _advance_latest_invoice(self, record: SubscriptionRecord, event: DunningEvent) -> None:
        record.mark_invoice_seen(event.invoice_id, event.invoice.created_unix)

    def process(self, event: DunningEvent) -> ProcessResult:
        record = self.store.ensure(event.subscription_id)
        from_state = record.state

        if event.event_id in self._handled_event_ids:
            return ProcessResult(
                event_id=event.event_id,
                subscription_id=event.subscription_id,
                invoice_id=event.invoice_id,
                applied=False,
                duplicate=True,
                from_state=from_state,
                to_state=record.state,
                reason="duplicate_event",
            )

        self._advance_latest_invoice(record, event)

        decision = decide(record, event)
        if decision.apply and decision.next_state is not None:
            record.state = decision.next_state
            if is_terminal_success(decision):
                record.resolve(event.invoice_id)
            if event.is_failure():
                record.last_failed_attempt = max(
                    record.last_failed_attempt, event.invoice.attempt
                )

        self._handled_event_ids.add(event.event_id)

        return ProcessResult(
            event_id=event.event_id,
            subscription_id=event.subscription_id,
            invoice_id=event.invoice_id,
            applied=decision.apply,
            duplicate=False,
            from_state=from_state,
            to_state=record.state,
            reason=decision.reason,
        )

    def process_many(self, events: list[DunningEvent]) -> list[ProcessResult]:
        return [self.process(event) for event in events]

    def process_in_stripe_order(self, events: list[DunningEvent]) -> list[ProcessResult]:
        """Replay a batch sorted by Stripe's creation order regardless of
        the order it was delivered to us."""
        return self.process_many(sort_by_stripe_order(events))

    def state_of(self, subscription_id: str) -> str | None:
        return self.store.state_of(subscription_id)

    def record_view(self, subscription_id: str) -> dict[str, object] | None:
        record = self.store.get(subscription_id)
        return None if record is None else describe_record(record)


def replay(events: list[DunningEvent], *, store: SubscriptionStore | None = None) -> WebhookProcessor:
    """Convenience: build a processor and feed it events in delivery order."""
    processor = WebhookProcessor(store=store)
    processor.process_many(events)
    return processor


def final_state_after(events: list[DunningEvent], subscription_id: str) -> str | None:
    processor = replay(events)
    return processor.state_of(subscription_id)


def applied_count(results: list[ProcessResult]) -> int:
    return sum(1 for r in results if r.applied)


def duplicate_count(results: list[ProcessResult]) -> int:
    return sum(1 for r in results if r.duplicate)


def is_paid_up(processor: WebhookProcessor, subscription_id: str) -> bool:
    return processor.state_of(subscription_id) == ACTIVE

